SysDataModelXML.SQLUpdateScript:
--LINKJSONDATASUBMIT --处理汇总
DECLARE @json NVARCHAR(MAX); SET @json = N'#LINKJSON{$.formData}#'; DECLARE @TABLE_1 NVARCHAR(MAX); SET @TABLE_1 = N'#LINKJSON{$.TABLE_1}#';
MERGE INTO PREQUL D USING ( SELECT GXFLG,PINNUM,DOCNUM,DOCLIN FROM OPENJSON(@TABLE_1) WITH ( GXFLG varchar(1) '$.GXFLG', -- 新增 GXFLG 字段 PINNUM varchar(30) '$.DOCNUM', DOCNUM varchar(30) '$.SRCDOC', DOCLIN int '$.SRCLIN' ) WHERE GXFLG = '1' -- 筛选 GXFLG 为 "1" 的记录 ) S ON D.DOCNUM = S.DOCNUM AND D.DOCLIN = S.DOCLIN WHEN MATCHED THEN UPDATE SET PINNUM = S.PINNUM;
--UPDATE PREQUL --SET PINNUM = '#DOCNUM#' --WHERE DOCNUM = '#SRCDOC#' -- AND DOCLIN = 0#SRCLIN# -- AND '#GXFLG#' = '1';
